package org.sleepwell.app;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;

public final class AlarmLifetimeTest {
    static final class Fake implements AlarmLifetime.Owner {String run="run";boolean replaceMode,replaceStop;int stops;List<Boolean> modes=new ArrayList<>();public boolean current(String expected){return run.equals(expected);}public boolean backupIfCurrent(String expected,boolean backup){if(replaceMode)run="replacement";if(!current(expected))return false;modes.add(backup);return true;}public boolean timeoutIfCurrent(String expected){if(replaceStop)run="replacement";if(!current(expected))return false;stops++;run="";return true;}}
    Alarm alarm(){Alarm a=new Alarm(1);a.backupMinutes=3;return a;}AlarmLifetime engine(Alarm a,Fake fake){return new AlarmLifetime(a,"run",fake);}
    @Test public void defaultsPreserveContinuousOneTimeEscalationAndNeverExpire(){Fake f=new Fake();AlarmLifetime life=engine(alarm(),f);assertTrue(life.tick(0,false));assertTrue(life.tick(180000,false));assertTrue(life.tick(180001,true));assertTrue(life.tick(Long.MAX_VALUE,true));assertEquals(List.of(false,true),f.modes);assertEquals(0,f.stops);}
    @Test public void boundedBurstReturnsToPrimaryAndRepeatsOnlyConfiguredTimes(){Alarm a=alarm();a.timing=new AlarmTiming(30,2,1,0);AlarmLifetime life=engine(a,new Fake());assertEquals(AlarmLifetime.Phase.PRIMARY,life.phase(179999,true));assertEquals(AlarmLifetime.Phase.BACKUP,life.phase(180000,true));assertEquals(AlarmLifetime.Phase.BACKUP,life.phase(209999,true));assertEquals(AlarmLifetime.Phase.PRIMARY,life.phase(210000,true));assertEquals(AlarmLifetime.Phase.PRIMARY,life.phase(269999,true));assertEquals(AlarmLifetime.Phase.BACKUP,life.phase(270000,true));assertEquals(AlarmLifetime.Phase.BACKUP,life.phase(360000,true));assertEquals(AlarmLifetime.Phase.PRIMARY,life.phase(390000,true));assertEquals(AlarmLifetime.Phase.PRIMARY,life.phase(Long.MAX_VALUE,true));}
    @Test public void serviceRestartOrLateDeliverySelectsCurrentPhaseWithoutReplayingMissedBursts(){Alarm a=alarm();a.timing=new AlarmTiming(60,1,2,0);Fake f=new Fake();AlarmLifetime restarted=engine(a,f);assertTrue(restarted.tick(250000,true));assertEquals(List.of(false),f.modes);assertTrue(restarted.tick(360000,true));assertEquals(List.of(false,true),f.modes);assertTrue(restarted.tick(420000,true));assertEquals(List.of(false,true,false),f.modes);assertTrue(engine(a,new Fake()).tick(900000,true));assertEquals(AlarmLifetime.Phase.PRIMARY,engine(a,new Fake()).phase(900000,true));}
    @Test public void forceFlagIsRequiredAndTimeoutPreemptsEvenAContinuousBackup(){Alarm a=alarm();a.timing=new AlarmTiming(0,0,5,5);Fake f=new Fake();AlarmLifetime life=engine(a,f);assertTrue(life.tick(180000,false));assertEquals(List.of(false),f.modes);assertTrue(life.tick(299999,true));assertFalse(life.tick(300000,true));assertEquals(1,f.stops);assertFalse(life.tick(400000,true));assertEquals(1,f.stops);}
    @Test public void quietAlarmsIgnoreAllTimingEscalationAndExpiry(){Alarm a=alarm();a.id=-1;a.timing=new AlarmTiming(30,5,15,1);Fake f=new Fake();AlarmLifetime life=engine(a,f);assertTrue(life.tick(Long.MAX_VALUE,true));assertEquals(List.of(false),f.modes);assertEquals(0,f.stops);}
    @Test public void replacementBetweenReadAndEffectCannotChangeOrStopAnotherOwner(){Alarm a=alarm();a.timing=new AlarmTiming(30,1,1,1);Fake mode=new Fake();mode.replaceMode=true;assertFalse(engine(a,mode).tick(0,false));assertTrue(mode.modes.isEmpty());Fake stop=new Fake();stop.replaceStop=true;assertFalse(engine(a,stop).tick(60000,true));assertEquals(0,stop.stops);assertEquals("replacement",stop.run);Fake already=new Fake();already.run="replacement";assertFalse(engine(a,already).tick(0,false));assertTrue(already.modes.isEmpty());}
    @Test public void closedOwnerCannotRearmAndInvalidSavedTimingNeverAddsAutoExpiry(){Alarm a=alarm();a.timing=new AlarmTiming(30,1,1,1);a.timingInvalid=true;Fake f=new Fake();AlarmLifetime life=engine(a,f);assertTrue(life.tick(999999,true));assertEquals(0,f.stops);life.close();assertFalse(life.tick(0,false));assertEquals(List.of(true),f.modes);}
    @Test public void constructorBoundsKeepSupportedSequenceWithinTwoHoursIncludingDelay(){Alarm a=alarm();a.backupMinutes=15;a.timing=new AlarmTiming(300,5,15,120);AlarmLifetime life=engine(a,new Fake());long finalBurstStart=15*60000L+5*(300000L+15*60000L);assertEquals(AlarmLifetime.Phase.BACKUP,life.phase(finalBurstStart,true));assertEquals(AlarmLifetime.Phase.EXPIRED,life.phase(120*60000L,true));for(int[] bad:new int[][]{{1,0,5,0},{301,0,5,0},{0,1,5,0},{30,6,5,0},{30,1,0,0},{30,1,16,0},{30,1,5,121},{30,1,5,-1}})assertThrows(IllegalArgumentException.class,()->new AlarmTiming(bad[0],bad[1],bad[2],bad[3]));}
    @Test public void immutableTimingEditsKeepTheOtherChoicesAndContinuousClearsRepeats(){AlarmTiming original=new AlarmTiming(60,2,3,15);AlarmTiming next=original.duration(0);assertEquals(0,next.backupRepeats);assertEquals(15,next.timeoutMinutes);assertEquals(2,original.backupRepeats);assertEquals(new AlarmTiming(60,2,3,15),original);assertEquals(2,original.gap(10).timeout(5).backupRepeats);}
}
